### Response:
Here is an algorithm in Java that finds all possible combinations of a given list of numbers, with the additional requirement that each combination must have at least one odd number:

```java
import java.util.ArrayList;
import java.util.List;

public class CombinationGenerator {

    public static void main(String[] args) {
        int[] lst = {1, 2, 3, 4};
        List<List<Integer>> combinations = generateCombinations(lst);

        for (List<Integer> combination : combinations) {
            System.out.println(combination);
        }
    }

    public static List<List<Integer>> generateCombinations(int[] lst) {
        List<List<Integer>> combinations = new ArrayList<>();
        List<Integer> currentCombination = new ArrayList<>();
        generateCombinationsHelper(lst, 0, currentCombination, combinations);
        return combinations;
    }

    public static void generateCombinationsHelper(int[] lst, int start, List<Integer> currentCombination, List<List<Integer>> combinations) {
        if (currentCombination.size() > 0 && currentCombination.stream().noneMatch(num -> num % 2 != 0)) {
            // If the current combination doesn't contain any odd number, discard it
            return;
        }

        combinations.add(new ArrayList<>(currentCombination));

        for (int i = start; i < lst.length; i++) {
            currentCombination.add(lst[i]);
            generateCombinationsHelper(lst, i + 1, currentCombination, combinations);
            currentCombination.remove(currentCombination.size() - 1);
        }
    }
}
```

